Algoritmo Products
  Dimension names[3] Como Cadena;
  Dimension prices[3] Como Entero;
  Para i <- 0 Hasta 2 Hacer
    Leer names[i];
    Leer prices[i];
  FinPara
  Para i <- 0 Hasta 2 Hacer
    Escribir names[i], " ", prices[i];
  FinPara
FinAlgoritmo

